// @name Todoist
// @background #f1f5f9
// @refresh 900
// Your Todoist tasks on the frame: what the scene's Filter finds ("today |
// overdue" by default, Todoist's Today view), narrowed to a project when the
// Project setting names one. Overdue tasks come first, in red, then day by
// day; a task's ring has its priority's color, and its project is on the
// right. Tap a ring to tick a task off in Todoist (tap again to take it back).
//
// The frame asks Todoist itself (todoist.ts), at the scene's refresh interval
// or when Refresh is tapped, and keeps what it read last in the scene's
// private `cache` field, so the list stays up when Todoist cannot be reached
// and a line says why.
import { buildQuery, colorHex, problemOf, projectRef, readProjects, readTasks, sendTick, sortTasks, titleOf } from './todoist'
import type { Task } from './todoist'
import {
  INKS, THEMES, clockText, dayKey, dayText, listScreen, nextDay, relativeDay, roundScreen, setRows, setScale, setupScreen, themeOf,
  tint,
} from './ui'
import type { Item, Part, RowView } from './ui'

const HOUR = 3600000

// ---------------------------------------------------------------- what is kept

// What the scene keeps between renders, in its private `cache` field (on
// disk, so a restart shows the list at once): the tasks as read last, when,
// the projects' names and colors, and what went wrong last.
export type Cache = {
  key: string
  at: number
  tasks: Task[]
  more: boolean
  projects: Record<string, [string, string]>
  pAt: number
  // The project the Project setting names, once found: its id and name.
  pid: string
  pname: string
  err: string
  // The last read failed: the list is the one from `at`.
  stale: boolean
  retryAt: number
}

type Settings = { token: string; filter: string; project: string }

const settingsOf = (app): Settings => ({
  token: String(app.state.apiToken || '').trim(),
  filter: String(app.state.filter ?? 'today | overdue').trim(),
  project: String(app.state.project || '').trim(),
})

// A short mark of the token, so a new one reads everything again without the
// token itself being kept twice.
const mark = (text: string) => {
  let h = 5381
  for (let i = 0; i < text.length; i++) h = ((h * 33) ^ text.charCodeAt(i)) >>> 0
  return h.toString(36)
}
const keyOf = (s: Settings) => `${mark(s.token)}|${s.filter}|${s.project}`

export function loadCache(app): Cache | null {
  let kept = app.state.cache
  if (typeof kept === 'string') {
    try {
      kept = kept ? JSON.parse(kept) : null
    } catch (e) {
      kept = null
    }
  }
  return kept && typeof kept === 'object' && Array.isArray(kept.tasks) ? kept : null
}
const save = (cache: Cache) => frameos.setState('cache', cache)

// ---------------------------------------------------------------- talking to Todoist

const short = (text: string) => (text.length > 30 ? `${text.slice(0, 29)}...` : text)

// Sends one tick (or its undo). A call that fails puts the tick back and
// says why; answers whether it went through.
function sendOne(token: string, cache: Cache, task: Task, now: number) {
  const op = task.send
  if (!op) return true
  delete task.send
  delete task.at
  const reply = sendTick(token, task, op)
  if (reply.ok) {
    if (!cache.stale) cache.err = ''
    return true
  }
  task.done = op !== 'close'
  cache.err = problemOf(reply, op === 'close' ? `tick off "${short(task.c)}"` : `reopen "${short(task.c)}"`).text
  return false
}

// Reads the projects when one is not known yet, or every six hours: their
// names and colors for the rows, and the Project setting's project.
function readProjectsIfDue(app, token: string, cache: Cache, now: number, want: boolean) {
  if (!want && now - cache.pAt < 6 * HOUR) return
  if (cache.pAt && now - cache.pAt < 10 * 60000) return
  const read = readProjects(token, app.frame.embedded ? 100 : 200)
  cache.pAt = now
  if (read.projects) cache.projects = read.projects
}

// Reads the tasks again: the filter, narrowed to the Project setting's
// project (and its sub-projects).
function refresh(app, s: Settings, cache: Cache, now: number) {
  const ref = projectRef(s.project)
  let projectName = ref.name
  if (ref.id || ref.name) {
    const find = () => {
      if (ref.id && cache.projects[ref.id]) return ref.id
      const lower = ref.name.toLowerCase()
      return Object.keys(cache.projects).find((id) => cache.projects[id][0].toLowerCase() === lower) || ''
    }
    if (!find()) readProjectsIfDue(app, s.token, cache, now, true)
    const id = find()
    cache.pid = id
    if (id) projectName = cache.projects[id][0]
    if (!projectName) {
      cache.err = `No project with the id ${ref.id} in Todoist. Check the scene's Project setting.`
      cache.stale = true
      cache.retryAt = now + 15 * 60000
      return
    }
  }
  cache.pname = projectName
  const read = readTasks(s.token, buildQuery(s.filter, projectName), app.frame.embedded ? 30 : 60)
  if (!read.tasks) {
    const problem = problemOf(read.reply, 'read the tasks')
    cache.err = problem.text
    cache.stale = true
    cache.retryAt = now + problem.waitMs
    return
  }
  cache.tasks = read.tasks
  cache.more = !!read.more
  cache.at = now
  cache.err = ''
  cache.stale = false
  cache.retryAt = 0
  readProjectsIfDue(app, s.token, cache, now, read.tasks.some((task) => task.pr && !cache.projects[task.pr]))
}

// Everything a render does before it draws: the ticks still to send, then
// a new read when the last one is as old as the scene's refresh interval.
export function sync(app, now: number): Cache {
  const s = settingsOf(app)
  const key = keyOf(s)
  let cache = loadCache(app)
  if (!cache || cache.key !== key) {
    const sameToken = cache && cache.key.split('|')[0] === key.split('|')[0]
    cache = {
      key, at: 0, tasks: [], more: false, projects: sameToken ? cache.projects : {}, pAt: sameToken ? cache.pAt : 0,
      pid: '', pname: '', err: '', stale: false, retryAt: 0,
    }
  }
  const before = JSON.stringify(cache)
  // A tick of the last few seconds is the sendTicks event's to send, after
  // the picture that shows it.
  for (const task of cache.tasks) if (task.send && !(now - (task.at || 0) < 5000)) sendOne(s.token, cache, task, now)
  const every = Math.max(60, Number(app.state.refreshInterval) || 900) * 1000
  if ((!cache.at || now - cache.at >= every - 30000) && now >= (cache.retryAt || 0)) refresh(app, s, cache, now)
  // Asked to wait less than the interval (no network, a busy Todoist): wake
  // for it.
  if (cache.retryAt > now && cache.retryAt - now < every) frameos.setNextSleep(Math.ceil((cache.retryAt - now) / 1000))
  if (JSON.stringify(cache) !== before) save(cache)
  return cache
}

// ---------------------------------------------------------------- what a tap does

let current = null
let shownIds: string[] = []

const fastPanel = (app) => (app.frame.fast ?? !app.frame.paper) !== false

// A tap on a task's ring: the tick shows at once, and Todoist is told. On a
// screen that answers at once the frame draws the tick first and sends it
// right after, on the scene's own `sendTicks` event (onEvent below), which
// goes round the queue once so the picture of the tap comes first: a failure
// puts the tick back and draws a line saying why. On e-paper, where each
// picture costs a refresh, it is sent before the one picture that answers the
// tap. A tick the frame had no time to send goes with a render seconds later.
export function toggle(app, i: number) {
  const s = settingsOf(app)
  const cache = loadCache(app)
  const task = cache?.tasks.find((each) => each.id === shownIds[i])
  if (!cache || !task || task.x || task.send) return
  // A recurring task ticked off has moved on to its next date: nothing to
  // take back.
  if (task.done && task.r) return
  task.done = !task.done
  task.send = task.done ? 'close' : 'reopen'
  task.at = Date.now()
  if (fastPanel(app) && typeof frameos.dispatch === 'function') {
    save(cache)
    frameos.dispatch('sendTicks', { hop: 1 })
    return
  }
  sendOne(s.token, cache, task, Date.now())
  save(cache)
}

// The ticks shown and not sent yet. A failure draws the list again (the tick
// back, and the line); a success leaves the picture as it is.
export function onEvent(app, context) {
  if (context.event !== 'sendTicks') return false
  // Once round the queue first, behind the render that shows the tap.
  if (context.payload?.hop === 1) {
    frameos.dispatch('sendTicks', { hop: 2 })
    return false
  }
  const cache = loadCache(app)
  if (!cache || !cache.tasks.some((task) => task.send)) return false
  const token = settingsOf(app).token
  let failed = false
  for (const task of cache.tasks) if (task.send && !sendOne(token, cache, task, Date.now())) failed = true
  save(cache)
  return failed
}

// Refresh: read the tasks (and the projects) again now.
export function refreshNow(app) {
  const cache = loadCache(app)
  if (!cache) return
  cache.at = 0
  cache.pAt = 0
  cache.retryAt = 0
  save(cache)
}

// ---------------------------------------------------------------- what the rows say

// "4 to do, 1 overdue, 2 done".
export function tallyOf(cache: Cache) {
  const today = dayKey(Date.now())
  let open = 0
  let late = 0
  let done = 0
  for (const task of cache.tasks) {
    if (task.done) done++
    else {
      open++
      if (task.d && task.d < today) late++
    }
  }
  if (!open && !done) return 'Nothing due'
  const parts = [`${open} to do`]
  if (late) parts.push(`${late} overdue`)
  if (done) parts.push(`${done} done`)
  return parts.join(', ')
}

// The ring of a priority (the API's 4 is Todoist's p1): red, orange, blue,
// and grey for none; solid inks on color e-paper; black on a panel with no
// color, where a P1 to P3 chip says it.
function ringOf(t, priority: number) {
  if (t === THEMES.color) {
    const color = ['#9ca3af', '#246fe0', '#eb8909', '#d1453b'][Math.min(4, Math.max(1, priority)) - 1]
    return { color, fill: priority > 1 ? tint(color, 0.88) : '#ffffff', width: 2 }
  }
  if (t === THEMES.inks) {
    const color = [INKS.black, INKS.blue, INKS.yellow, INKS.red][Math.min(4, Math.max(1, priority)) - 1]
    return { color, fill: '#ffffff', width: priority > 1 ? 3 : 2 }
  }
  return { color: '#000000', fill: '#ffffff', width: priority >= 4 ? 4 : priority === 3 ? 3 : 2 }
}

export function viewOf(app, cache: Cache, now: number) {
  const t = themeOf(app)
  const twelve = app.state.clock === '12'
  const today = dayKey(now)
  const tomorrow = nextDay(today)
  const items: Item[] = []
  const rows: RowView[] = []
  const ids: string[] = []
  let section = ''
  for (const task of sortTasks(cache.tasks)) {
    const late = !!task.d && task.d < today
    const head = !task.d ? 'No date' : late ? 'Overdue' : task.d === today ? `Today · ${dayText(today, today)}` : task.d === tomorrow ? 'Tomorrow' : dayText(task.d, today)
    if (head !== section) {
      items.push({ head, late })
      section = head
    }
    const parts: Part[] = []
    const time = task.t ? clockText(task.t, twelve) : ''
    if (late) parts.push({ text: time ? `${relativeDay(task.d, today)} ${time}` : relativeDay(task.d, today), cls: task.done ? t.muted : t.late })
    else if (time) parts.push({ text: time, cls: task.t < now && !task.done ? t.late : t.muted })
    if (task.r) parts.push({ icon: 'repeat' })
    if (t === THEMES.high && task.p > 1) parts.push({ text: `P${5 - task.p}`, chip: task.p === 4 ? 'bg-black text-white font-bold' : 'border border-black font-bold' })
    const project = cache.projects[task.pr]
    const right = project && task.pr !== cache.pid ? { text: project[0], dot: t === THEMES.color ? colorHex(project[1]) : undefined } : undefined
    rows.push({ key: task.id, text: task.c, done: !!task.done, ring: task.x ? null : ringOf(t, task.p), parts, right })
    ids.push(task.id)
    items.push({ row: rows.length - 1 })
  }
  return { t, items, rows, ids }
}

// ---------------------------------------------------------------- the picture

export function get(app, context) {
  current = app
  const round = context?.round === true
  const W = context?.imageWidth ?? app.frame.width
  const H = context?.imageHeight ?? app.frame.height
  const side = Math.min(W, H)
  setScale(!round && side >= 900 ? Math.min(3, Math.floor((side / 480) * 2) / 2) : 1)
  const t = themeOf(app)
  const s = settingsOf(app)
  if (!s.token) {
    return setupScreen(t, W, H, round, 'key', 'Connect Todoist', 'This scene shows your Todoist tasks and needs your API token to read them.', [
      { head: 'Copy your API token', text: 'In Todoist: Settings, Integrations, Developer, Copy API token.' },
      { head: "Paste it in this scene's settings", text: 'Under API token. It stays on the frame, like a password.' },
      { head: 'Pick what to show', text: 'Filter takes Todoist\'s filters; Project narrows it to one project.', code: 'today | overdue' },
    ])
  }
  const now = Date.now()
  const cache = sync(app, now)
  if (!cache.at && cache.err) {
    return setupScreen(t, W, H, round, 'alert', 'Could not read your tasks', cache.err, [
      { head: 'Check the API token', text: 'Todoist: Settings, Integrations, Developer. Copy it again into the scene\'s API token.' },
      { head: 'Check the filter', text: 'It is written as in Todoist\'s own filters, and a project as it is named there.', code: s.filter || 'today | overdue' },
    ])
  }
  const view = viewOf(app, cache, now)
  shownIds = view.ids
  setRows(view.rows, (i) => toggle(current, i))
  const title = String(app.state.title || '').trim() || titleOf(s.filter, cache.pname)
  const problem = cache.err ? (cache.stale && cache.at ? `${cache.err} Showing the tasks from ${clockText(cache.at, app.state.clock === '12')}.` : cache.err) : ''
  const screen = {
    t: view.t,
    title,
    tally: tallyOf(cache),
    updated: cache.at ? clockText(cache.at, app.state.clock === '12') : '',
    problem,
    items: view.items,
    empty: 'Nothing due. Enjoy the day.',
    endNote: cache.more ? 'More tasks in Todoist' : '',
    onRefresh: () => refreshNow(current),
  }
  return round ? roundScreen(screen, W, H) : listScreen(screen, W, H)
}

sources.todoist.ts:
// Todoist's API v1 (developer.todoist.com/api/v1), the calls this scene makes:
//   GET  /api/v1/tasks/filter?query=...&limit=N   the tasks a filter finds: {results, next_cursor}
//   GET  /api/v1/projects?limit=N                 the projects, for their names and colors
//   POST /api/v1/tasks/{id}/close                 tick a task off (204; a recurring one moves on)
//   POST /api/v1/tasks/{id}/reopen                take the tick back (204)
// Every call carries "Authorization: Bearer <the API token>". Nothing lets a
// client choose the fields a task comes with, so a page is kept small (limit)
// and each task is cut down to what a row shows as soon as it is read.

export const API = 'https://api.todoist.com/api/v1'

// A task as the scene keeps it: its words, its day ("2026-11-28", "" for none)
// and time (ms, 0 for a whole day), recurring, priority (the API's: 4 is p1),
// project, its place in Todoist's order, and whether it can be ticked at all
// (a task written "* Heading" cannot). done, send and at are the frame's own:
// a tick shown, the call still to make for it, and when it was tapped.
export type Task = {
  id: string
  c: string
  d: string
  t: number
  r: boolean
  p: number
  pr: string
  o: number
  x?: boolean
  done?: boolean
  send?: 'close' | 'reopen'
  at?: number
}

export type Reply = { status: number; body?: string; error?: string; headers?: Record<string, string> }

export function call(token: string, method: string, path: string): Reply {
  const reply = frameos.httpRequest(API + path, {
    method,
    headers: { Authorization: `Bearer ${token}`, Accept: 'application/json' },
    timeoutMs: 15000,
  })
  return { status: reply.status || 0, body: reply.body, error: reply.error, headers: reply.headers }
}

const ok = (reply: Reply) => reply.status >= 200 && reply.status < 300

// ---------------------------------------------------------------- reading tasks

// Todoist's content is Markdown: a link's words, bold and code marks dropped.
export function plainText(text: string) {
  return String(text || '')
    .replace(/\[([^\]]*)\]\([^)]*\)/g, '$1')
    .replace(/\*\*|__|~~|`/g, '')
    .replace(/\s+/g, ' ')
    .trim()
}

const pad2 = (n: number) => String(n).padStart(2, '0')
const dayOfMs = (ms: number) => {
  const d = new Date(ms)
  return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`
}

// A due date as Todoist sends it, in `due.date`: a whole day "2026-11-28", a
// floating time "2026-11-28T14:00:00" (the frame's own clock) or a fixed one
// in UTC "2026-11-28T13:00:00.000000Z". The day is the frame's.
export function parseDue(date: any): { d: string; t: number } {
  const m = /^(\d{4})-(\d\d)-(\d\d)(?:T(\d\d):(\d\d)(?::(\d\d))?(?:\.\d+)?(Z|[+-]\d\d:?\d\d)?)?$/.exec(String(date || ''))
  if (!m) return { d: '', t: 0 }
  const [y, mo, d] = [Number(m[1]), Number(m[2]), Number(m[3])]
  if (m[4] === undefined) return { d: `${m[1]}-${m[2]}-${m[3]}`, t: 0 }
  const [h, mi, s] = [Number(m[4]), Number(m[5]), Number(m[6] || 0)]
  let ms: number
  if (!m[7]) ms = new Date(y, mo - 1, d, h, mi, s).getTime()
  else {
    ms = Date.UTC(y, mo - 1, d, h, mi, s)
    if (m[7] !== 'Z') {
      const off = /([+-])(\d\d):?(\d\d)/.exec(m[7])
      if (off) ms -= (off[1] === '-' ? -1 : 1) * (Number(off[2]) * 60 + Number(off[3])) * 60000
    }
  }
  return { d: dayOfMs(ms), t: ms }
}

// One task of the API's, cut down to what a row shows.
export function slimTask(raw: any, index: number): Task {
  let text = plainText(raw.content)
  // "* Heading": a task Todoist shows without a checkbox.
  const x = /^\*\s/.test(String(raw.content || ''))
  if (x) text = text.replace(/^\*\s*/, '')
  const due = raw.due ? parseDue(raw.due.date) : { d: '', t: 0 }
  const task: Task = {
    id: String(raw.id),
    c: text || '(no title)',
    d: due.d,
    t: due.t,
    r: !!(raw.due && raw.due.is_recurring),
    p: Number(raw.priority) || 1,
    pr: String(raw.project_id || ''),
    o: typeof raw.day_order === 'number' && raw.day_order >= 0 ? raw.day_order : 1000 + index,
  }
  if (x) task.x = true
  return task
}

// The order a list of tasks reads in: overdue first, then day by day, the
// tasks with a time by their time before the rest of that day by priority,
// and those with no date last.
export function sortTasks(tasks: Task[]) {
  return [...tasks].sort((a, b) => {
    if (a.d !== b.d) {
      if (!a.d) return 1
      if (!b.d) return -1
      return a.d < b.d ? -1 : 1
    }
    if (!!a.t !== !!b.t) return a.t ? -1 : 1
    if (a.t !== b.t) return a.t - b.t
    if (a.p !== b.p) return b.p - a.p
    return a.o - b.o
  })
}

// ---------------------------------------------------------------- the query

// A project's name in a filter, as Todoist's filter syntax wants it: a space
// or a sign that means something there is written after a backslash
// ("#Shopping\ list", "#One \& Two").
export function escapeName(name: string) {
  return String(name).trim().replace(/([\\\s&|!()#@,*])/g, '\\$1')
}

// The scene's Filter, narrowed to a project and its sub-projects when the
// Project setting names one.
export function buildQuery(filter: string, projectName: string) {
  const query = String(filter || '').trim()
  const project = String(projectName || '').trim()
  if (!project) return query || 'today | overdue'
  const scope = `##${escapeName(project)}`
  return query ? `(${query}) & ${scope}` : scope
}

// The Project setting: a name as Todoist shows it, an id ("6Jf8VQXxpwv56VQ7")
// or a project's link from the web app (".../app/project/work-6Jf8VQXxpwv56VQ7").
export function projectRef(text: string): { id: string; name: string } {
  const value = String(text || '').trim()
  if (!value) return { id: '', name: '' }
  if (/^https?:\/\//i.test(value) || /todoist\.com\//i.test(value)) {
    const byQuery = /[?&]id=([0-9A-Za-z]+)/.exec(value)
    if (byQuery) return { id: byQuery[1], name: '' }
    const path = value.split(/[?#]/)[0].replace(/\/+$/, '')
    const last = path.slice(path.lastIndexOf('/') + 1)
    return { id: last.slice(last.lastIndexOf('-') + 1), name: '' }
  }
  // An id is letters and digits, sixteen of them in API v1; a name may be
  // that too, so a name is tried when no project has it as its id.
  if (/^[0-9A-Za-z]{16}$/.test(value)) return { id: value, name: value }
  return { id: '', name: value }
}

// What a title says for a filter: "Today" for Todoist's Today view's filter.
export function titleOf(filter: string, projectName: string) {
  const q = String(filter || '').trim().toLowerCase().replace(/\s+/g, ' ')
  if (projectName && (!q || q === 'today | overdue' || q === 'overdue | today')) return projectName
  if (!q || q === 'today | overdue' || q === 'overdue | today' || q === 'today') return 'Today'
  if (q === 'tomorrow') return 'Tomorrow'
  if (projectName) return projectName
  const words = String(filter).trim()
  return words.length > 28 ? `${words.slice(0, 27)}...` : words
}

// ---------------------------------------------------------------- what went wrong

// A reply that is no success, as a line for the screen, and how long to
// leave Todoist alone before asking again.
export function problemOf(reply: Reply, doing: string): { text: string; waitMs: number } {
  let message = ''
  let retryAfter = 0
  try {
    const body = reply.body ? JSON.parse(reply.body) : null
    if (body && typeof body === 'object') {
      message = String(body.error || '')
      const extra = body.error_extra || {}
      if (extra.retry_after) retryAfter = Number(extra.retry_after) || 0
      if (extra.argument && extra.expected) message = `${message}: ${extra.argument} ${extra.expected}`
      else if (extra.explanation) message = `${message}: ${extra.explanation}`
    }
  } catch (e) {
    message = String(reply.body || '').slice(0, 120)
  }
  const header = Number(reply.headers?.['retry-after'] || 0)
  if (header > retryAfter) retryAfter = header
  const status = reply.status
  if (!status) {
    const why = reply.error || 'no answer'
    if (why.startsWith('Local network access is off')) return { text: why, waitMs: 120000 }
    return { text: `Could not reach Todoist to ${doing}: ${why}.`, waitMs: 120000 }
  }
  if (status === 401) return { text: "Todoist refused the API token. Check the scene's API token setting.", waitMs: 15 * 60000 }
  if (status === 403) return { text: `Todoist would not let this token ${doing}${message ? ` (${message})` : ''}.`, waitMs: 15 * 60000 }
  if (status === 429) {
    const wait = Math.max(60, retryAfter)
    return { text: `Todoist asks to slow down. Trying again in ${Math.ceil(wait / 60)} min.`, waitMs: wait * 1000 }
  }
  if (status === 400) return { text: `Todoist could not ${doing}: ${message || 'bad request'}.`, waitMs: 15 * 60000 }
  if (status === 404) return { text: `Todoist could not ${doing}: ${message || 'not found'}.`, waitMs: 15 * 60000 }
  return { text: `Todoist had trouble (HTTP ${status}) and could not ${doing}.`, waitMs: Math.max(120, retryAfter) * 1000 }
}

// ---------------------------------------------------------------- the calls

// One page of the tasks a query finds, at most `limit` of them.
export function readTasks(token: string, query: string, limit: number): { tasks?: Task[]; more?: boolean; reply: Reply } {
  const reply = call(token, 'GET', `/tasks/filter?query=${encodeURIComponent(query)}&limit=${limit}`)
  if (!ok(reply)) return { reply }
  let data: any = null
  try {
    data = JSON.parse(reply.body || 'null')
  } catch (e) {
    return { reply: { status: 502, body: '', error: 'an answer that is no JSON' } }
  }
  const results = data && Array.isArray(data.results) ? data.results : []
  const tasks = results.slice(0, limit).map((raw: any, i: number) => slimTask(raw, i))
  return { tasks, more: !!(data && data.next_cursor), reply }
}

// The projects' names and colors, {id: [name, color]}.
export function readProjects(token: string, limit: number): { projects?: Record<string, [string, string]>; reply: Reply } {
  const reply = call(token, 'GET', `/projects?limit=${limit}`)
  if (!ok(reply)) return { reply }
  const projects: Record<string, [string, string]> = {}
  try {
    const data = JSON.parse(reply.body || 'null')
    for (const project of data && Array.isArray(data.results) ? data.results : []) {
      if (project && project.id) projects[String(project.id)] = [String(project.name || ''), String(project.color || 'charcoal')]
    }
  } catch (e) {
    return { reply: { status: 502, body: '', error: 'an answer that is no JSON' } }
  }
  return { projects, reply }
}

// Ticks a task off, or takes the tick back. A task already gone (completed
// or deleted elsewhere) is as good as ticked off.
export function sendTick(token: string, task: Task, op: 'close' | 'reopen'): Reply & { ok: boolean } {
  const reply = call(token, 'POST', `/tasks/${encodeURIComponent(task.id)}/${op}`)
  return { ...reply, ok: ok(reply) || (op === 'close' && reply.status === 404) }
}

// Todoist's project colors by name (the API's "Colors" table); a name it
// does not know is charcoal, as the docs say.
const COLORS = {
  berry_red: '#b8255f', red: '#dc4c3e', orange: '#c77100', yellow: '#b29104', olive_green: '#949c31',
  lime_green: '#65a33a', green: '#369307', mint_green: '#42a393', teal: '#148fad', sky_blue: '#319dc0',
  light_blue: '#6988a4', blue: '#4180ff', grape: '#692ec2', violet: '#ca3fee', lavender: '#a4698c',
  magenta: '#e05095', salmon: '#c9766f', charcoal: '#808080', grey: '#999999', taupe: '#8f7a69',
}
export const colorHex = (name: string) => COLORS[name] || COLORS.charcoal

