// The list's look: themes, sizes, the header, the rows and the setup screen.
// The app works out what each row says (rowViews) and what happens on a tap
// (setTickHandler); this file only draws it.

// High contrast where the panel shows no color (black and white, greys), or
// when the scene's Contrast setting asks for it.
const highContrast = (app) => {
  const mode = app.state.contrast || 'auto'
  return mode === 'high' || (mode === 'auto' && app.frame.color === false)
}

export const THEMES = {
  color: {
    name: 'color',
    page: 'bg-slate-100 text-slate-800',
    muted: 'text-slate-500',
    card: 'bg-white',
    head: 'text-slate-500',
    late: 'text-[#d1453b]',
    lateHead: 'text-[#d1453b]',
    doneText: 'text-slate-400 line-through',
    button: 'bg-white text-slate-600 active:bg-slate-200',
    banner: 'bg-amber-100 text-amber-900',
    tick: '#ffffff',
    icon: 'bg-white text-slate-600',
    step: 'bg-slate-800 text-white',
    code: 'bg-slate-200 text-slate-800',
  },
  high: {
    name: 'high',
    page: 'bg-white text-black',
    muted: 'text-black',
    card: 'bg-white border-2 border-black',
    head: 'text-black',
    late: 'text-black font-bold',
    lateHead: 'text-black',
    doneText: 'text-black line-through',
    button: 'bg-white text-black border-2 border-black',
    banner: 'bg-black text-white',
    tick: '#ffffff',
    icon: 'bg-white text-black border-2 border-black',
    step: 'bg-black text-white',
    code: 'bg-white text-black border-2 border-black',
  },
}

// Color e-paper (Spectra's six inks): the high-contrast page with what is
// colored in solid inks, as the panel shows them (dither.nim's measured
// table), so nothing is dithered into confetti.
export const INKS = { black: '#191426', red: '#6b1119', yellow: '#c7bb00', blue: '#18539a', green: '#2a5531' }
THEMES.inks = {
  ...THEMES.high,
  name: 'inks',
  late: `text-[${INKS.red}] font-bold`,
  lateHead: `text-[${INKS.red}]`,
  banner: `bg-[${INKS.red}] text-white`,
  step: `bg-[${INKS.blue}] text-white`,
}

export const themeOf = (app) => {
  if (highContrast(app)) return THEMES.high
  if ((app.state.contrast || 'auto') === 'auto' && app.frame.paper === true) return THEMES.inks
  return THEMES.color
}

// A panel of 900 px or more on its shorter side at render scale 1 (a 13.3"
// color e-paper, 1200 px) draws everything that much larger (K), by halves:
// S() turns Tailwind's sizes in a class list into pixels times K. Elsewhere K
// is 1 and the classes stay as they are.
let K = 1
export const setScale = (k: number) => {
  K = k
}
export const k = (n: number) => Math.round(n * K)
const TEXT = { xs: [12, 16], sm: [14, 20], base: [16, 24], lg: [18, 28], xl: [20, 28], '2xl': [24, 32], '3xl': [30, 36], '4xl': [36, 40] }
const RADII = { lg: 8, xl: 12, '2xl': 16 }
export const S = (cls: string) => (K === 1 ? cls : cls.split(' ').map((c) => {
  let m = /^text-(xs|sm|base|lg|xl|2xl|3xl|4xl)$/.exec(c)
  if (m) return `text-[${Math.round(TEXT[m[1]][0] * K)}px] leading-[${Math.round(TEXT[m[1]][1] * K)}px]`
  m = /^rounded-(lg|xl|2xl)$/.exec(c)
  if (m) return `rounded-[${Math.round(RADII[m[1]] * K)}px]`
  m = /^border-(\d+)$/.exec(c)
  if (m) return `border-[${Math.round(Number(m[1]) * K)}px]`
  m = /^(h|w|p|px|py|pl|pr|pt|pb|gap|min-w)-(\d+)$/.exec(c)
  if (m) return `${m[1]}-[${Math.round(Number(m[2]) * 4 * K)}px]`
  return c
}).join(' '))

// A color a share of the way to white: the tint inside a ring.
export const tint = (hex: string, share: number) => {
  const n = parseInt(hex.slice(1), 16)
  const mix = (v: number) => Math.round(v + (255 - v) * share).toString(16).padStart(2, '0')
  return `#${mix((n >> 16) & 255)}${mix((n >> 8) & 255)}${mix(n & 255)}`
}

// ---------------------------------------------------------------- icons

const PATHS = {
  check: 'M5 12l5 5L20 7',
  calendar: 'M8 2v4M16 2v4M3 10h18M5 4h14a2 2 0 0 1 2 2v14a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V6a2 2 0 0 1 2-2z',
  person: 'M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2M12 11a4 4 0 1 0 0-8 4 4 0 0 0 0 8z',
  link: 'M10 13a5 5 0 0 0 7.5.5l3-3a5 5 0 0 0-7-7l-1.7 1.7M14 11a5 5 0 0 0-7.5-.5l-3 3a5 5 0 0 0 7 7l1.7-1.7',
  database: 'M12 8c4.4 0 8-1.3 8-3s-3.6-3-8-3-8 1.3-8 3 3.6 3 8 3zM4 5v14c0 1.7 3.6 3 8 3s8-1.3 8-3V5M4 12c0 1.7 3.6 3 8 3s8-1.3 8-3',
  refresh: 'M20 11a8 8 0 0 0-14.9-3M4 4v4h4M4 13a8 8 0 0 0 14.9 3M20 20v-4h-4',
  alert: 'M12 9v4M12 17h.01M10.3 3.9L1.8 18a2 2 0 0 0 1.7 3h17a2 2 0 0 0 1.7-3L13.7 3.9a2 2 0 0 0-3.4 0z',
  repeat: 'M17 2l4 4-4 4M3 11v-1a4 4 0 0 1 4-4h14M7 22l-4-4 4-4M21 13v1a4 4 0 0 1-4 4H3',
  key: 'M2.5 18.5V22h4v-3h3v-3h2l1.4-1.4A6 6 0 1 0 9.4 11.1L2.5 18z M16.5 7.5h.01',
  list: 'M9 6h11M9 12h11M9 18h11M4 6h.01M4 12h.01M4 18h.01',
  done: 'M22 11.1V12a10 10 0 1 1-5.9-9.1M22 4L12 14l-3-3',
}

export const Icon = ({ name, cls = 'w-5 h-5', width = 2 }) => (
  <svg className={S(cls)} viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth={width} strokeLinecap="round" strokeLinejoin="round">
    <path d={PATHS[name]} />
  </svg>
)

// ---------------------------------------------------------------- what the rows say

// One part of a row's second line: text in classes of its own, with an icon
// or a colored dot before it, or a chip (classes for its box).
export type Part = { text?: string; cls?: string; icon?: string; dot?: string; chip?: string }
// A row: its words, whether it is ticked, its ring (null: nothing to tick;
// square for a checkbox) and its second line.
export type RowView = {
  key: string
  text: string
  done: boolean
  ring: null | { color: string; fill: string; width: number; square?: boolean }
  parts: Part[]
  right?: Part
}
// What the list holds in order: a heading, or a row by its index.
export type Item = { head: string; late?: boolean } | { row: number }

// What a tap on a ring does: the app's, set with the rows each render. A
// tap is a whole render: the tick, the tally and any line come from the
// state the app keeps, so the picture never shows what was not kept.
let views: RowView[] = []
let onTick: (i: number) => void = () => {}
export function setRows(rows: RowView[], handler: (i: number) => void) {
  views = rows
  onTick = handler
}

// On a small panel a part's icon gives its room to the words, when it has
// words.
const PartView = ({ part, t, small }) => {
  if (part.chip) {
    return (
      <span className={S(`shrink-0 flex items-center gap-1 rounded-lg ${small ? 'px-1' : 'px-2'} ${part.chip}`)}>
        {part.dot ? <span className={S(`w-2 h-2 shrink-0 rounded-full bg-[${part.dot}]`)} /> : null}
        <span>{part.text}</span>
      </span>
    )
  }
  return (
    <span className={S(`flex items-center gap-1 min-w-0 ${part.cls ?? t.muted}`)}>
      {part.dot ? <span className={S(`w-2 h-2 shrink-0 rounded-full bg-[${part.dot}]`)} /> : null}
      {part.icon && !(small && part.text) ? <Icon name={part.icon} cls={small ? 'w-3 h-3 shrink-0' : 'w-4 h-4 shrink-0'} /> : null}
      {part.text ? <span className="truncate">{part.text}</span> : null}
    </span>
  )
}

// `z.small`: a watch, a 2.8" LCD, a small e-paper or a small circle: less
// padding, smaller type.
const Row = memo(({ i, v, t, small }) => {
  const view = v as RowView
  const done = view.done
  const ring = view.ring
  const box = small ? 'w-6 h-6' : 'w-7 h-7'
  const words = small ? 'text-base' : 'text-lg'
  const line = small ? 'text-xs' : 'text-sm'
  const right = view.right
  return (
    <div className={S(`${small ? 'h-12 gap-2 pl-2 pr-2 rounded-xl' : 'h-16 gap-3 pl-3 pr-4 rounded-2xl'} shrink-0 flex items-center ${t.card}`)}>
      {ring ? (
        <div className={S(`${small ? 'w-9 h-12' : 'w-10 h-16'} shrink-0 flex items-center justify-center`)}
          title={done ? 'Mark as not done' : 'Mark as done'}
          onClick={() => onTick(i)}>
          <div className={S(`${box} ${ring.square ? 'rounded-lg' : 'rounded-full'} flex items-center justify-center`) + ` border-[${k(ring.width)}px] border-[${ring.color}] bg-[${done ? ring.color : ring.fill}]`}>
            {done ? <Icon name="check" cls={small ? 'w-4 h-4 text-white' : 'w-5 h-5 text-white'} width={3} /> : null}
          </div>
        </div>
      ) : (
        <div className={S(`${small ? 'w-9' : 'w-10'} shrink-0 flex items-center justify-center`)}>
          <div className={S(`w-2 h-2 rounded-full`) + ` bg-[${t.name === 'color' ? '#94a3b8' : '#000000'}]`} />
        </div>
      )}
      <div className="flex-1 min-w-0 flex flex-col justify-center">
        <span className={S(`${words} truncate ${done ? t.doneText : ''}`)}>{view.text}</span>
        {view.parts.length || right ? (
          <div className={S(`flex items-center ${small ? 'gap-2' : 'gap-3'} ${line}`)}>
            {view.parts.map((part) => <PartView part={part} t={t} small={small} />)}
            {right ? <span className="flex-1 min-w-0" /> : null}
            {right ? <PartView part={right} t={t} small={small} /> : null}
          </div>
        ) : null}
      </div>
    </div>
  )
})

const Head = ({ text, late, t, small }) => (
  <div className={S(`${small ? 'h-6 text-xs pl-1' : 'h-8 text-sm pl-2'} shrink-0 flex items-end font-bold uppercase ${late ? t.lateHead : t.head}`)}>
    {text}
  </div>
)

const Tally = ({ t, small, text }) => <span className={S(`${small ? 'text-xs' : 'text-base'} ${t.muted} truncate`)}>{text}</span>

// The heights the list is laid out with (Tailwind's: h-16 is 64 px), so its
// box holds whole rows and no row shows cut in half at the bottom.
const ROW = { small: 48, big: 64 }
const HEAD = { small: 24, big: 32 }
const GAP = 8

function fitHeight(items: Item[], small: boolean, room: number) {
  let used = 0
  let fitted = 0
  for (let n = 0; n < items.length; n++) {
    const item = items[n] as any
    const h = k(item.head !== undefined ? (small ? HEAD.small : HEAD.big) : small ? ROW.small : ROW.big)
    const next = used + (n ? k(GAP) : 0) + h
    if (next > room) break
    used = next
    fitted = n + 1
  }
  // A heading never ends the box: the row it heads goes with it.
  if (fitted > 0 && fitted < items.length && (items[fitted - 1] as any).head !== undefined) {
    used -= k((small ? HEAD.small : HEAD.big) + GAP)
    fitted--
  }
  return fitted >= items.length ? 0 : Math.max(used, k(small ? ROW.small : ROW.big))
}

// How tall the whole list is.
function listHeight(items: Item[], small: boolean) {
  let used = 0
  items.forEach((item: any, n) => {
    used += (n ? k(GAP) : 0) + k(item.head !== undefined ? (small ? HEAD.small : HEAD.big) : small ? ROW.small : ROW.big)
  })
  return used
}

const listOf = (items: Item[], t, small: boolean, endNote: string, scrolls: boolean) => (
  <div className={S(`flex flex-col gap-2${scrolls ? ' pr-2' : ''}`)}>
    {items.map((item: any) =>
      item.head !== undefined ? <Head text={item.head} late={item.late} t={t} small={small} /> : <Row i={item.row} v={views[item.row]} t={t} small={small} />,
    )}
    {endNote ? <span className={S(`${small ? 'text-xs' : 'text-sm'} ${t.muted} text-center py-2`)}>{endNote}</span> : null}
  </div>
)

export type Screen = {
  t: any
  title: string
  tally: string
  updated: string
  problem: string
  items: Item[]
  empty: string
  endNote: string
  onRefresh: () => void
}

const Banner = ({ t, small, text }) => (
  <div className={S(`${small ? 'h-12 px-2 gap-2 text-xs rounded-xl' : 'h-14 px-3 gap-3 text-sm rounded-xl'} shrink-0 flex items-center ${t.banner}`)}>
    <Icon name="alert" cls={small ? 'w-4 h-4 shrink-0' : 'w-5 h-5 shrink-0'} />
    <span className="flex-1 min-w-0 line-clamp-2">{text}</span>
  </div>
)

const Empty = ({ t, small, text }) => (
  <div className={S(`flex-1 flex flex-col items-center justify-center gap-2 ${t.muted}`)}>
    <Icon name="done" cls={small ? 'w-10 h-10' : 'w-14 h-14'} width={1.5} />
    <span className={S(`${small ? 'text-base' : 'text-lg'} text-center`)}>{text}</span>
  </div>
)

const RefreshButton = ({ t, small, updated, onRefresh }) => (
  <div className={S(`${small ? 'h-8 px-2 gap-1 text-xs' : 'h-10 px-3 gap-2 text-sm'} shrink-0 flex items-center rounded-xl ${t.button}`)}
    title="Refresh" onClick={onRefresh}>
    <Icon name="refresh" cls={small ? 'w-4 h-4' : 'w-5 h-5'} />
    {updated ? <span>{updated}</span> : null}
  </div>
)

// The list on a rectangle: the title and the tally, a line when something
// went wrong, and the rows in a box that scrolls.
export function listScreen(screen: Screen, W: number, H: number) {
  const { t } = screen
  const small = Math.min(W, H) < 320
  const pad = k(small ? 12 : 24)
  const gap = k(small ? 8 : 12)
  const headH = k(small ? 44 : 40)
  const bannerH = screen.problem ? k(small ? 48 : 56) + gap : 0
  const room = H - 2 * pad - headH - gap - bannerH
  const boxH = fitHeight(screen.items, small, room)
  return (
    <div className={S(`flex flex-col w-full h-full ${small ? 'gap-2 p-3' : 'gap-3 p-6'} ${t.page}`)}>
      {small ? (
        <div className="h-[44px] shrink-0 flex items-center gap-2">
          <div className="flex-1 min-w-0 flex flex-col">
            <span className="text-xl font-bold truncate">{screen.title}</span>
            <Tally t={t} small={small} text={screen.tally} />
          </div>
          <RefreshButton t={t} small={small} updated={screen.updated} onRefresh={screen.onRefresh} />
        </div>
      ) : (
        <div className={S('h-10 gap-3 shrink-0 flex items-center')}>
          <span className={S('text-3xl font-bold truncate')}>{screen.title}</span>
          <div className="flex-1 min-w-0 flex justify-end">
            <Tally t={t} small={small} text={screen.tally} />
          </div>
          <RefreshButton t={t} small={small} updated={screen.updated} onRefresh={screen.onRefresh} />
        </div>
      )}
      {screen.problem ? <Banner t={t} small={small} text={screen.problem} /> : null}
      {screen.items.length ? (
        <div className="flex-1 min-h-0 flex flex-col">
          <div className={`${boxH ? `h-[${boxH}px] min-h-0` : 'flex-1 min-h-0'} overflow-y-auto`}>
            {listOf(screen.items, t, small, screen.endNote, boxH > 0)}
          </div>
        </div>
      ) : (
        <Empty t={t} small={small} text={screen.empty} />
      )}
    </div>
  )
}

// On a round panel: the title and the tally in the arc at the top, the rows
// as wide as the circle lets them be, the refresh button in the arc below.
export function roundScreen(screen: Screen, W: number, H: number) {
  const { t } = screen
  const cx = W / 2
  const cy = H / 2
  const R = Math.min(W, H) / 2 - 12
  const chord = (dy: number) => Math.floor(2 * Math.sqrt(Math.max(0, R * R - dy * dy)))
  // The compact rows up to a 520 px circle: more of them fit between the arcs.
  const small = R < 248
  const headTop = Math.round(R * 0.9)
  const headH = small ? 32 + 20 : 36 + 24
  const headW = chord(headTop)
  const listTop = Math.min(Math.round(R * 0.62), headTop - headH - 6)
  const footH = small ? 32 : 40
  const footBottom = Math.round(R * 0.86)
  const listBottom = footBottom - footH - 10
  const listW = Math.min(chord(listTop), chord(listBottom))
  const bannerH = screen.problem ? (small ? 48 : 56) + 8 : 0
  const room = listTop + listBottom - bannerH
  const fitted = screen.items.length ? fitHeight(screen.items, small, room) || Math.min(room, listHeight(screen.items, small)) : room
  // What is left over goes above and below, so the rows and the button sit
  // in the middle of the room under the title.
  const spare = Math.max(0, room - fitted)
  const top = cy - listTop + (spare >> 1)
  return (
    <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
      <div className={`absolute left-[${Math.round(cx - headW / 2)}px] top-[${Math.round(cy - headTop)}px] w-[${headW}px] flex flex-col items-center`}>
        <span className={`${small ? 'text-2xl' : 'text-3xl'} font-bold truncate`}>{screen.title}</span>
        <Tally t={t} small={small} text={screen.tally} />
      </div>
      <div className={`absolute left-[${Math.round(cx - listW / 2)}px] top-[${Math.round(top)}px] w-[${listW}px] h-[${fitted + bannerH}px] flex flex-col gap-2`}>
        {screen.problem ? <Banner t={t} small={small} text={screen.problem} /> : null}
        {screen.items.length ? (
          <div className={`h-[${fitted}px] overflow-y-auto`}>{listOf(screen.items, t, small, screen.endNote, fitted < listHeight(screen.items, small))}</div>
        ) : (
          <Empty t={t} small={small} text={screen.empty} />
        )}
      </div>
      <div className={`absolute left-0 top-[${Math.round(top + fitted + bannerH + 10)}px] w-[${W}px] h-[${footH}px] flex justify-center`}>
        <RefreshButton t={t} small={small} updated={screen.updated} onRefresh={screen.onRefresh} />
      </div>
    </div>
  )
}

// ---------------------------------------------------------------- setup and trouble

export type Step = { head: string; text: string; code?: string }

// What to do before there is anything to show (no token yet), or why there
// is nothing (the first read failed): a title, a line, and numbered steps.
export function setupScreen(t, W: number, H: number, round: boolean, icon: string, title: string, intro: string, steps: Step[]) {
  // On a round panel it goes in the square inside the circle, its type at
  // its smallest.
  const side = round ? Math.floor((Math.min(W, H) / 2 - 12) * Math.SQRT2) : 0
  const w = round ? side : W
  const h = round ? side : H
  const small = round || Math.min(w, h) < 360
  // A small rectangle (a 2.8" LCD) has room for two lines of each.
  const tight = small && !round
  // The steps side by side only where each has room for its words.
  const wide = !small && w >= 960 && w > h * 1.4
  const body = (
    <div className={S(`flex flex-col justify-center w-full h-full ${small ? 'gap-2 p-2' : 'gap-4 p-8'} ${round ? '' : t.page}`)}>
      <div className={S(`flex items-center ${small ? 'gap-2' : 'gap-4'}`)}>
        <div className={S(`${small ? 'w-10 h-10' : 'w-14 h-14'} shrink-0 rounded-full flex items-center justify-center ${t.icon}`)}>
          <Icon name={icon} cls={small ? 'w-5 h-5' : 'w-7 h-7'} />
        </div>
        <div className="flex-1 min-w-0 flex flex-col">
          <span className={S(`${tight ? 'text-base' : small ? 'text-lg' : 'text-3xl'} font-bold leading-tight`)}>{title}</span>
          <span className={S(`${small ? 'text-xs' : 'text-base'} ${t.muted} ${small && !tight ? 'line-clamp-3' : 'line-clamp-2'}`)}>{intro}</span>
        </div>
      </div>
      <div className={S(`${wide ? 'flex flex-row' : 'flex flex-col'} ${small ? 'gap-1' : 'gap-3'} min-h-0`)}>
        {steps.map((step, index) => (
          <div className={S(`${wide ? 'flex-1 min-w-0' : ''} flex ${small ? 'gap-2 px-2 py-1 rounded-xl' : 'gap-3 px-4 py-3 rounded-2xl'} ${t.card}`)}>
            <div className={S(`${small ? 'w-5 h-5 text-xs' : 'w-7 h-7 text-sm'} shrink-0 rounded-full flex items-center justify-center font-bold ${t.step}`)}>
              {index + 1}
            </div>
            <div className="flex-1 min-w-0 flex flex-col">
              <span className={S(`${small ? 'text-sm' : 'text-lg'} font-semibold`)}>{step.head}</span>
              <span className={S(`${tight ? 'text-xs line-clamp-2' : small ? 'text-xs line-clamp-3' : 'text-sm'} ${t.muted}`)}>{step.text}</span>
              {step.code && !small ? <span className={S(`self-start mt-1 rounded-lg px-2 font-mono text-sm ${t.code}`)}>{step.code}</span> : null}
            </div>
          </div>
        ))}
      </div>
    </div>
  )
  if (!round) return body
  return (
    <div className={`relative w-[${W}px] h-[${H}px] ${t.page}`}>
      <div className={`absolute left-[${(W - side) >> 1}px] top-[${(H - side) >> 1}px] w-[${side}px] h-[${side}px]`}>{body}</div>
    </div>
  )
}

// ---------------------------------------------------------------- time as text

const WEEKDAYS = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat']
const MONTHS = ['Jan', 'Feb', 'Mar', 'Apr', 'May', 'Jun', 'Jul', 'Aug', 'Sep', 'Oct', 'Nov', 'Dec']
const pad2 = (n: number) => String(n).padStart(2, '0')

// "2026-11-28" for a moment, in the frame's time zone.
export const dayKey = (ms: number) => {
  const d = new Date(ms)
  return `${d.getFullYear()}-${pad2(d.getMonth() + 1)}-${pad2(d.getDate())}`
}
const dayOf = (key: string) => {
  const [y, m, d] = key.split('-').map(Number)
  return new Date(y, m - 1, d)
}
// The day after a day key: "2026-11-29".
export const nextDay = (key: string) => {
  const d = dayOf(key)
  return dayKey(new Date(d.getFullYear(), d.getMonth(), d.getDate() + 1, 12).getTime())
}
// "17:05", or "5:05 pm" on a 12-hour clock.
export const clockText = (ms: number, twelve: boolean) => {
  const d = new Date(ms)
  const h = d.getHours()
  if (!twelve) return `${h}:${pad2(d.getMinutes())}`
  return `${h % 12 || 12}:${pad2(d.getMinutes())} ${h < 12 ? 'am' : 'pm'}`
}
// "Fri 28 Nov" for a day key; with the year when it is not this one.
export const dayText = (key: string, todayKey: string) => {
  const d = dayOf(key)
  const text = `${WEEKDAYS[d.getDay()]} ${d.getDate()} ${MONTHS[d.getMonth()]}`
  return key.slice(0, 4) === todayKey.slice(0, 4) ? text : `${text} ${d.getFullYear()}`
}
// "28 Nov", shorter, for a row.
export const shortDay = (key: string, todayKey: string) => {
  const d = dayOf(key)
  const text = `${d.getDate()} ${MONTHS[d.getMonth()]}`
  return key.slice(0, 4) === todayKey.slice(0, 4) ? text : `${text} ${d.getFullYear()}`
}
// How a day reads next to today: "Today", "Yesterday", "Tomorrow", or "28 Nov".
export const relativeDay = (key: string, todayKey: string) => {
  if (key === todayKey) return 'Today'
  if (key === nextDay(todayKey)) return 'Tomorrow'
  if (nextDay(key) === todayKey) return 'Yesterday'
  return shortDay(key, todayKey)
}

